# ── Font registration ─────────────────────────────────────────────────────────
MONTH_MAP = {
    'APRIL':1,'MAY':2,'JUNE':3,'JULY':4,'AUGUST':5,
    'SEPTEMBER':6,'OCTOBER':7,'NOVEMBER':8,'DECEMBER':9,
    'JANUARY':10,'FEBRUARY':11,'MARCH':12
}

def detect_months_from_header(text):
    h = str(text).upper()
    found = [v for k,v in MONTH_MAP.items() if k in h]
    return max(found) if found else None

# ── Month extraction from header ─────────────────────────────────────────────
MONTH_ORDER = {
    'APRIL':1,'MAY':2,'JUNE':3,'JULY':4,'AUGUST':5,
    'SEPTEMBER':6,'OCTOBER':7,'NOVEMBER':8,'DECEMBER':9,
    'JANUARY':10,'FEBRUARY':11,'MARCH':12
}

def extract_months_from_header(header_str):
    """Extract number of months from header like 'SALES APRIL - JUNE 2025-2026'"""
    header = str(header_str).upper()
    months_found = [m for m in MONTH_ORDER if m in header]
    if len(months_found) >= 2:
        sorted_months = sorted(months_found, key=lambda m: MONTH_ORDER[m])
        return MONTH_ORDER[sorted_months[-1]] - MONTH_ORDER[sorted_months[0]] + 1
    elif len(months_found) == 1:
        return 1
    return None

def extract_period_label(header_str):
    """Extract period label like 'April - June' from header"""
    import re
    header = str(header_str)
    # Try to find two month names
    pattern = r'(April|May|June|July|August|September|October|November|December|January|February|March)'
    months = re.findall(pattern, header, re.IGNORECASE)
    if len(months) >= 2:
        return f"{months[0].capitalize()} – {months[-1].capitalize()}"
    elif len(months) == 1:
        return months[0].capitalize()
    return 'YTD'

@st.cache_resource
def register_fonts():
    import os
    font_paths = [
        '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
        '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
    ]
    # Try system fonts first, then bundled
    for path in font_paths:
        if not os.path.exists(path):
            st.error(f"Font not found: {path}. Please ensure DejaVu fonts are installed.")
            return False
    pdfmetrics.registerFont(TTFont('DVSans', font_paths[0]))
    pdfmetrics.registerFont(TTFont('DVSans-Bold', font_paths[1]))
    pdfmetrics.registerFontFamily('DVSans', normal='DVSans', bold='DVSans-Bold')
    return True

register_fonts()

